/**
 * SignGraph — the predication site: the small category SignCells generate.
 *
 * A site is a finite set of cells (as triples) together with specialization
 * morphisms between predicates. Its base category has two sorts of object —
 * entities (the terms in subject and object position) and predicates — and is
 * generated by the cell moves: converse (s,p,o) → (o,p,s), the subject and
 * object projections onto (s,p,s) and (o,p,o), and specialization, which
 * refines only the predicate coordinate: a morphism from a general predicate
 * to a specialized one (RDFS subPropertyOf, read general → specialized).
 * Everything valued over cells — fibers, presheaves, the sheaf on the foam —
 * is valued over this base.
 *
 * Specialization transports evidence: a telling for (s, q, o), q specializing
 * p, tells (s, p, o) for (RDFS entailment rule rdfs7); a telling against
 * (s, p, o) tells (s, q, o) against. `transportRules` states these as SignChain
 * rules over the site's cells, for SignCraft to settle.
 *
 * Terms are opaque values compared by SignCell coincidence (canonical bytes).
 * Evidence is not part of a site: a site is where values can be, not what they are.
 */
import { cell, coincidenceKey, coincides, triple, tripleKey } from "@red-cup-engineering/signcell/cell";
import { rule } from "@red-cup-engineering/signchain/rules";

// Distinct values by coincidence, first occurrence kept, in one pass over canonical-byte keys
// (comparing every value with every kept one was quadratic in the number of cells).
const uniqueBy = (values, keyOf) => {
  const seen = new Map();
  for (const value of values) {
    const key = keyOf(value);
    if (!seen.has(key)) seen.set(key, value);
  }
  return Object.freeze([...seen.values()]);
};

/** A specialization morphism: from a general predicate to a specialized one. */
export const specializationMorphism = (specialized, general) => Object.freeze({ kind: "signgraph.specialization", domain: general, codomain: specialized });
export const isSpecializationMorphism = (value) => value !== null && typeof value === "object" && value.kind === "signgraph.specialization";

/** The distinct entity terms (subjects and objects) of a list of cells. */
export const entitiesOf = (cells) => uniqueBy(cells.flatMap((value) => [value.subject, value.object]), coincidenceKey);
/** The distinct predicate terms of a list of cells. */
export const predicatesOf = (cells) => uniqueBy(cells.map((value) => value.predicate), coincidenceKey);

function baseCategory(cells, entities, predicates, specializations) {
  const node = (value) => Object.freeze([value.subject, value.predicate, value.object]);
  return Object.freeze({
    kind: "signgraph.base",
    objects: Object.freeze([...entities.map((term) => Object.freeze({ sort: "entity", term })), ...predicates.map((term) => Object.freeze({ sort: "predicate", term }))]),
    specialization: Object.freeze([...specializations]),
    converse: Object.freeze(cells.map((value) => Object.freeze({ domain: node(value), codomain: Object.freeze([value.object, value.predicate, value.subject]) }))),
    subjectProjection: Object.freeze(cells.map((value) => Object.freeze({ domain: node(value), codomain: value.subject }))),
    objectProjection: Object.freeze(cells.map((value) => Object.freeze({ domain: node(value), codomain: value.object }))),
  });
}

/** A site over cells (any SignCells or triples) and specialization morphisms, given in one list or two. */
export function site(witnesses, specializations = []) {
  const all = [...witnesses, ...specializations];
  const cells = uniqueBy(all.filter((value) => !isSpecializationMorphism(value)).map(triple), tripleKey);
  const morphisms = Object.freeze(all.filter(isSpecializationMorphism));
  const entities = entitiesOf(cells), predicates = predicatesOf(cells);
  return Object.freeze({ kind: "signgraph.site", cells, entities, predicates, specializations: morphisms, base: baseCategory(cells, entities, predicates, morphisms) });
}

/** Every cell E × Π × E over the given entities and predicates. */
export const generatedCells = (entities, predicates) => Object.freeze(entities.flatMap((subject) => predicates.flatMap((predicate) => entities.map((object) => triple(cell(subject, predicate, object))))));

/** The site an utterance (token, claim) generates: E = {token}, Π = {claim}, so its one cell is (token, claim, token). */
export const utteranceSite = (token, claim) => site(generatedCells([token], [claim]));

/** A site's generators, its stored presentation: cells and specializations only. */
export const presentSite = (value) => Object.freeze({ kind: "signgraph.site", cells: value.cells, specializations: value.specializations });
/** The full site back from its generators. */
export const freeSite = (generators) => site(generators.cells, generators.specializations);

/** The base with its specialization relation transitively closed. */
export function closeSpecialization(base) {
  const edges = base.specialization.map((edge) => [edge.domain, edge.codomain]);
  const has = (domain, codomain) => edges.some(([d, c]) => coincides(d, domain) && coincides(c, codomain));
  let changed = true;
  while (changed) {
    changed = false;
    for (const [leftDomain, leftCodomain] of [...edges]) {
      for (const [rightDomain, rightCodomain] of [...edges]) {
        if (coincides(leftCodomain, rightDomain) && !has(leftDomain, rightCodomain)) { edges.push([leftDomain, rightCodomain]); changed = true; }
      }
    }
  }
  return Object.freeze({ ...base, specialization: Object.freeze(edges.map(([domain, codomain]) => Object.freeze({ kind: "signgraph.specialization", domain, codomain }))) });
}

/** Cohere a site: its cells, and the residue with specialization closed. */
export const cohere = (value) => Object.freeze({ kind: "signgraph.coherence", saturated: value.cells, residue: Object.freeze({ ...value, base: closeSpecialization(value.base) }) });

/** The ordered predicate pairs no (closed) specialization relates. */
export function unrelatedPairs(value) {
  const closed = closeSpecialization(value.base);
  const related = (domain, codomain) => closed.specialization.some((edge) => coincides(edge.domain, domain) && coincides(edge.codomain, codomain));
  const edges = [];
  for (const domain of value.predicates) for (const codomain of value.predicates) if (!related(domain, codomain)) edges.push(Object.freeze({ domain, codomain }));
  return Object.freeze({ kind: "signgraph.unrelatedPairs", edges: Object.freeze(edges) });
}

/** The rules by which a site's (closed) specializations transport evidence between its cells:
 *  for-evidence up from the specialized predicate to the general one, against-evidence down. */
export function transportRules(value) {
  const closed = closeSpecialization(value.base);
  const has = (at) => value.cells.some((other) => coincides(triple(other), triple(at)));
  const rules = [];
  for (const edge of closed.specialization) {
    for (const at of value.cells) {
      if (!coincides(at.predicate, edge.codomain)) continue;
      const general = triple(cell(at.subject, edge.domain, at.object));
      if (!has(general)) continue;
      rules.push(rule(`specialization-for:${JSON.stringify([at.subject, edge.codomain, edge.domain, at.object])}`, [{ cell: at, atLeast: "potential" }], { cell: general, reading: "potential" }));
      rules.push(rule(`specialization-against:${JSON.stringify([at.subject, edge.domain, edge.codomain, at.object])}`, [{ cell: general, atLeast: "active" }], { cell: at, reading: "active" }));
    }
  }
  return Object.freeze(rules);
}

/** The JSON Schema of a site's generators. */
export const siteGeneratorsSchema = Object.freeze({
  $id: "https://schemas.561.group/signgraph/site-generators.schema.json",
  type: "object",
  required: ["kind", "cells", "specializations"],
  properties: {
    kind: { const: "signgraph.site" },
    cells: { type: "array", items: { type: "object", required: ["subject", "predicate", "object"], properties: { subject: {}, predicate: {}, object: {} }, additionalProperties: false } },
    specializations: { type: "array", items: { type: "object", required: ["kind", "domain", "codomain"], properties: { kind: { const: "signgraph.specialization" }, domain: {}, codomain: {} }, additionalProperties: false } },
  },
  additionalProperties: false,
  title: "SiteGenerators",
  description: "The cells and specializations a predication site is freely constructed from.",
});
